rows=[]
for name in ['kaupamex-api','kaupamex-docs','thyrox']:
 root=Path('/workspace')/name
 for kind,resolver in [('workbench',workbench_dir),('jobs',jobs_dir),('cache',cache_dir)]:
  row={'repo':name,'kind':kind,'interface':resolver.__module__+'.'+resolver.__name__,'readonly_unwrapped':True}
  try:
   path=inspect.unwrap(resolver)(root);row['resolved_path']=str(path);row['exists']=path.exists();row['inside_owner']=path.is_relative_to(root)
   if row['inside_owner'] and path.exists():
